const ctx = $items('Video Gate')[0]?.json;

if (!ctx) {
  throw new Error('VIDEO_CONTEXT_NOT_FOUND');
}

const raw = $json?.message?.content;

if (!raw) {
  throw new Error('OLLAMA_EMPTY_RESPONSE');
}

let plan;

try {
  plan = JSON.parse(raw);
} catch {
  throw new Error('OLLAMA_INVALID_JSON: ' + raw);
}

const script = String(plan.script || '').trim();

const terms = Array.isArray(plan.search_terms)
  ? plan.search_terms.map(x => String(x).trim()).filter(Boolean)
  : [];

if (!script) {
  throw new Error('SCRIPT_EMPTY');
}

if (terms.length < 1) {
  throw new Error('SEARCH_TERMS_EMPTY');
}

return [{
  json:{
    ...ctx,
    video_script:script,
    video_terms:terms
  }
}];
